//! The plugin's permissions (one per command, `permissions/autogenerated/`) and its Kotlin side
//! (`android/`: the native player, E6b-D1, its output, E6b-D10, and the folders the person chose
//! in Android's folder picker, E6b-D9), which Tauri's Android build includes in the app's Gradle
//! project.

/// The commands the page calls; the Kotlin plugin answers them (`PlayerPlugin.kt`), and the two
/// listener commands are Tauri's own, for the plugin's events.
const COMMANDS: &[&str] = &[
    "set_queue",
    "set_upcoming",
    "play",
    "pause",
    "seek",
    "stop",
    "status",
    "set_output",
    "output_info",
    "pick_folder",
    "folder_check",
    "folder_walk",
    "folder_list",
    "folder_stat",
    "folder_read",
    "folder_write",
    "folder_delete",
    "folder_rename",
    "folder_mkdir",
    "folder_address",
    "safe_area",
    "spectrum",
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
